import{_ as e,o,c as i,a2 as r}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Ley Simbiótica del Trabajo","description":"","frontmatter":{},"headers":[],"relativePath":"es/41-共生劳动法.md","filePath":"es/41-共生劳动法.md"}'),n={name:"es/41-共生劳动法.md"};function t(s,a,l,d,c,u){return o(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="ley-simbiotica-del-trabajo" tabindex="-1">Ley Simbiótica del Trabajo <a class="header-anchor" href="#ley-simbiotica-del-trabajo" aria-label="Permalink to &quot;Ley Simbiótica del Trabajo&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>41</td></tr><tr><td>Módulo</td><td>Sistema Legal y Marco de Gobernanza</td></tr><tr><td>Palabras clave</td><td>Trabajo simbiótico, Más trabajo más recompensa, Derechos laborales, Contratación conjunta de producción, Antiexplotación</td></tr></tbody></table><h2 id="i-proposito-legislativo-y-principios-basicos" tabindex="-1">I. Propósito Legislativo y Principios Básicos <a class="header-anchor" href="#i-proposito-legislativo-y-principios-basicos" aria-label="Permalink to &quot;I. Propósito Legislativo y Principios Básicos&quot;">​</a></h2><p>La <em>Ley Simbiótica del Trabajo</em> es una de las leyes centrales del sistema legal de la Civilización Simbiótica del Ancla, al mismo nivel que la <em>Constitución Simbiótica</em>. Su objetivo es regular todas las actividades de trabajo y contribución dentro del Universo Hengyuan, establecer el orden de distribución de &quot;más trabajo, más recompensa; autocrecimiento y autodesarrollo&quot; y erradicar, a nivel legal, el terreno de la explotación depredadora.</p><p>Esta Ley establece los siguientes principios básicos:</p><table tabindex="0"><thead><tr><th>Principio</th><th>Contenido</th></tr></thead><tbody><tr><td>Dignidad del Trabajo</td><td>Todo trabajo legal está protegido por la ley; la dignidad personal del trabajador no debe ser vulnerada</td></tr><tr><td>Más Trabajo, Más Recompensa</td><td>La remuneración del trabajo está directamente vinculada al monto de la contribución; cuanto mayor la contribución, mayor el ingreso; se prohíbe el lucro sin trabajo</td></tr><tr><td>Trabajo Voluntario</td><td>El trabajo forzado y la esclavitud están prohibidos; los trabajadores tienen derecho a elegir libremente el contenido y la forma del trabajo</td></tr><tr><td>Remuneración Justa</td><td>A igual trabajo, igual salario; se prohíbe la discriminación salarial basada en raza, cultivo u origen</td></tr><tr><td>Protección Laboral</td><td>El estado y la civilización tienen la obligación de proporcionar a los trabajadores un entorno laboral seguro y seguridad social básica</td></tr><tr><td>Colaboración Simbiótica</td><td>Se fomenta la colaboración y ayuda mutua entre trabajadores; se combaten la competencia viciosa y los juegos de suma cero</td></tr></tbody></table><h2 id="ii-derechos-basicos-de-los-trabajadores" tabindex="-1">II. Derechos Básicos de los Trabajadores <a class="header-anchor" href="#ii-derechos-basicos-de-los-trabajadores" aria-label="Permalink to &quot;II. Derechos Básicos de los Trabajadores&quot;">​</a></h2><p>La Ley Simbiótica del Trabajo confiere a todas las formas de vida con capacidad laboral dentro del Universo Hengyuan los siguientes derechos:</p><ol><li><strong>Derecho a la Igualdad de Empleo</strong>: Ninguna vida debe ser discriminada en la búsqueda y ejercicio del empleo por motivos de raza, cultivo, origen, género u otros factores.</li><li><strong>Derecho a la Libre Elección de Ocupación</strong>: Los trabajadores tienen derecho a elegir su profesión, puesto y lugar de trabajo según su voluntad y capacidad, y derecho a cambiar de ocupación conforme a la ley.</li><li><strong>Derecho a la Remuneración Razonable</strong>: Los trabajadores tienen derecho a recibir una remuneración acorde a su contribución laboral; la remuneración no debe ser inferior al estándar mínimo de garantía establecido por la civilización.</li><li><strong>Derecho al Descanso y Vacaciones</strong>: Los trabajadores tienen derecho a una distribución razonable del tiempo de trabajo y a vacaciones periódicas; se prohíbe la extensión ilimitada de la jornada laboral.</li><li><strong>Derecho a la Seguridad Laboral</strong>: Los trabajadores tienen derecho a trabajar en un entorno seguro e higiénico; los empleadores deben proporcionar condiciones de protección laboral que cumplan los estándares.</li><li><strong>Derecho a la Formación Profesional</strong>: Los trabajadores tienen derecho a recibir formación en habilidades profesionales y orientación de cultivo; los empleadores y el estado tienen la obligación de proporcionar recursos de formación.</li><li><strong>Derecho de Asociación y Consulta</strong>: Los trabajadores tienen derecho a organizar o unirse a asociaciones de trabajadores conforme a la ley, y derecho a proteger sus propios intereses mediante la consulta colectiva.</li><li><strong>Derecho de Apelación y Reparación</strong>: Cuando los derechos laborales son vulnerados, los trabajadores tienen derecho a presentar apelaciones y demandas ante las instituciones de arbitraje laboral y el Tribunal Simbiótico.</li></ol><h2 id="iii-legalizacion-del-mecanismo-de-contratacion-conjunta-de-produccion" tabindex="-1">III. Legalización del Mecanismo de Contratación Conjunta de Producción <a class="header-anchor" href="#iii-legalizacion-del-mecanismo-de-contratacion-conjunta-de-produccion" aria-label="Permalink to &quot;III. Legalización del Mecanismo de Contratación Conjunta de Producción&quot;">​</a></h2><p>El Mecanismo de Contratación Conjunta de Producción es la institución central de distribución de recursos de la Civilización Simbiótica del Ancla; la <em>Ley Simbiótica del Trabajo</em> la fija en forma legal:</p><ul><li><strong>Sujetos Contratantes</strong>: Cualquier vida con capacidad laboral puede ser sujeto contratante; tanto individuos como colectivos pueden contratar.</li><li><strong>Contenido del Contrato</strong>: Incluye, entre otros, el desarrollo de recursos de cultivo, el mantenimiento de planos, la transmisión del conocimiento, la investigación tecnológica, los servicios públicos y otros campos.</li><li><strong>Plazo del Contrato</strong>: Determinado según la naturaleza del contenido contratado; los contratos a corto plazo duran de uno a tres años, los de largo plazo de cinco a veinte años, con posibilidad de renovación al vencimiento.</li><li><strong>Distribución de Ingresos</strong>: El ingreso del contratante está directamente vinculado a la producción; parte de la producción se entrega a la acumulación pública y el resto pertenece al contratante.</li><li><strong>Mecanismo de Salida</strong>: El contratante tiene derecho a salir del contrato tras aviso previo dentro de un plazo razonable; no debe ser forzado a permanecer en la relación contractual.</li><li><strong>Resolución de Disputas</strong>: Las disputas contractuales se resuelven preferentemente mediante arbitraje laboral; quien no esté conforme con el laudo puede demandar ante el Tribunal Simbiótico.</li></ul><h2 id="iv-proteccion-laboral-especial" tabindex="-1">IV. Protección Laboral Especial <a class="header-anchor" href="#iv-proteccion-laboral-especial" aria-label="Permalink to &quot;IV. Protección Laboral Especial&quot;">​</a></h2><p>Ante las necesidades especiales de las distintas formas de vida dentro del Universo Hengyuan, esta Ley establece instituciones de protección laboral especial:</p><table tabindex="0"><thead><tr><th>Grupo Protegido</th><th>Medidas Especiales de Protección</th></tr></thead><tbody><tr><td>Cultivadores principiantes</td><td>No debe asignarse trabajo de alto riesgo que supere su capacidad; debe proporcionarse orientación de mentor</td></tr><tr><td>Vidas femeninas en gestación y parto</td><td>Derecho a licencia de maternidad remunerada de no menos de seis meses; no debe asignarse trabajo de alta intensidad durante la lactancia</td></tr><tr><td>Vidas discapacitadas y lesionadas</td><td>Derecho a ajuste razonable del puesto y a garantías de entorno laboral sin barreras</td></tr><tr><td>Trabajadores de otras razas</td><td>Los empleadores deben respetar las características fisiológicas y costumbres culturales de las razas no humanas y proporcionar condiciones laborales adaptadas</td></tr><tr><td>Trabajadores de edad avanzada</td><td>Pueden solicitar reducción de la intensidad laboral o traslado a puestos consultivos al alcanzar cierta edad</td></tr></tbody></table><h2 id="v-responsabilidad-legal-y-garantias-de-implementacion" tabindex="-1">V. Responsabilidad Legal y Garantías de Implementación <a class="header-anchor" href="#v-responsabilidad-legal-y-garantias-de-implementacion" aria-label="Permalink to &quot;V. Responsabilidad Legal y Garantías de Implementación&quot;">​</a></h2><p>Los empleadores que violen las disposiciones de esta Ley asumirán las siguientes responsabilidades según la gravedad de las circunstancias:</p><ol><li>Pagar la remuneración debida al trabajador y la indemnización (indemnización de una a tres veces los atrasos).</li><li>Ser ordenados a rectificar en un plazo determinado; si no rectifican, pagar multas.</li><li>En circunstancias graves, se revoca la licencia de operación y se prohíbe a los responsables ejercer funciones de gestión durante un período determinado.</li><li>Si constituye delito, se persigue la responsabilidad penal conforme a la ley.</li></ol><p>El estado establece instituciones de inspección laboral, responsables de supervisar e inspeccionar el cumplimiento de la ley laboral por parte de los empleadores. Las asociaciones de trabajadores tienen derecho a representar a los trabajadores en la inspección laboral y la consulta colectiva.</p><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>La <em>Ley Simbiótica del Trabajo</em> es el vehículo legal de la filosofía de &quot;más trabajo, más recompensa&quot; de la Civilización Simbiótica del Ancla. Transforma el trabajo de objeto de explotación en derecho respetado, y la distribución de apropiación depredadora en retribución basada en la contribución, sentando una base institucional laboral sólida para el avance conjunto de las Diez Mil Razas.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Constitución Simbiótica: Principios Generales)</li><li>06-多劳多得分配原理 (Principios de Distribución Más Trabajo Más Recompensa)</li><li>22-资源分配联产承包机制 (Mecanismo de Contratación Conjunta de Producción para la Distribución de Recursos)</li><li>42-消费者保护法 (Ley de Protección al Consumidor)</li></ul>',23)])])}const m=e(n,[["render",t]]);export{p as __pageData,m as default};
